      "path": "labs/DeliveryLab/fixtures/changed-constraint.json",
      "source": "{\n  \"schemaVersion\": 1,\n  \"author\": \"synthetic-author\",\n  \"artifact\": {\n    \"bundleID\": \"example.delivery.scratch\",\n    \"version\": \"1.0\",\n    \"build\": \"42\",\n    \"environment\": \"sandbox\",\n    \"configuration\": \"Release\",\n    \"sourceRevision\": \"synthetic-revision-2\",\n    \"binaryImages\": [\n      {\n        \"name\": \"Scratch\",\n        \"architecture\": \"arm64\",\n        \"uuid\": \"abcdef01-2345-4678-9abc-def012345678\"\n      }\n    ]\n  },\n  \"expected\": {\n    \"bundleID\": \"example.delivery.scratch\",\n    \"version\": \"1.0\",\n    \"build\": \"42\",\n    \"environment\": \"sandbox\",\n    \"configuration\": \"Release\",\n    \"sourceRevision\": \"synthetic-revision-2\"\n  },\n  \"symbolImages\": [\n    {\n      \"name\": \"Scratch\",\n      \"architecture\": \"arm64\",\n      \"uuid\": \"abcdef01-2345-4678-9abc-def012345678\"\n    }\n  ],\n  \"resources\": [\n    \"PrivacyInfo.xcprivacy\",\n    \"en.lproj\"\n  ],\n  \"requiredResources\": [\n    \"PrivacyInfo.xcprivacy\",\n    \"en.lproj\"\n  ],\n  \"expectedEntitlements\": {\n    \"application-identifier\": \"SYNTHETIC.example.delivery.scratch\",\n    \"aps-environment\": \"development\"\n  },\n  \"observedEntitlements\": {\n    \"application-identifier\": \"SYNTHETIC.example.delivery.scratch\",\n    \"aps-environment\": \"development\"\n  },\n  \"effectiveSettingsChecked\": false,\n  \"signatureChecked\": false,\n  \"profileChecked\": false,\n  \"packagingChecked\": false,\n  \"diagnosticKind\": \"crash\",\n  \"evidence\": [\n    {\n      \"id\": \"fixture-tests\",\n      \"kind\": \"host-test\",\n      \"path\": \"fixtures/synthetic-result.txt\",\n      \"sha256\": \"8ce59cc281d9eb07c3df148631e6195bda2ba87afd9395a3f22b43c77c506801\",\n      \"provenance\": \"synthetic\",\n      \"revision\": \"synthetic-revision-2\"\n    }\n  ],\n  \"review\": {\n    \"state\": \"proposed\",\n    \"reviewer\": \"\",\n    \"reviewedFingerprint\": \"\",\n    \"revisionNote\": \"\",\n    \"findings\": []\n  },\n  \"consumers\": [\n    {\n      \"id\": \"extension\",\n      \"owner\": \"synthetic-extension-owner\",\n      \"decisionRight\": \"Accept consumer parity or request exception\",\n      \"state\": \"exception\",\n      \"evidenceID\": \"\",\n      \"exception\": {\n        \"owner\": \"synthetic-extension-owner\",\n        \"reason\": \"A widget reads shared durable state; a process-local actor does not serialize both processes.\",\n        \"reviewDate\": \"2027-01-10\",\n        \"compensatingCheck\": \"Retain old compatible store reader; require interprocess migration evidence before removing it.\"\n      }\n    }\n  ],\n  \"installedCompatibilityOwner\": \"synthetic-service-owner\"\n}\n",
